def _branches(panel, x):
    from scipy.special import expit
    from scipy.optimize import least_squares
    u = panel['u']
    out = []
    for (key, f, initial) in [('v1', lambda w: w / (1 + np.abs(w)), 0.84), ('v2', lambda w: w * expit(w), 1.45)]:
        v = panel[key]

        def design(z, h):
            return _design(np.column_stack((z, f(h[0] * z))))

        def residual(h):
            A = design(u, h)
            return (A @ _ls(A, v) - v).ravel()
        h = least_squares(residual, [initial], bounds=(0.15, 5)).x
        A = design(u, h)
        out.append(design(x, h) @ _ls(A, v))
    return out

def _time_basis(t, traj):
    from scipy.optimize import least_squares

    def basis(rate):
        return -np.expm1(-t[:, None] * rate)

    def residual(rate):
        H = basis(rate)
        return (H @ _ls(H, traj.T) - traj.T).ravel()
    rate = least_squares(residual, [1.8, 0.4], bounds=([0.7, 0.02], [6.0, 1.2])).x
    return basis(rate)
